'use client';

import { ark, type HTMLArkProps } from '@ark-ui/react/factory';
import {
  Select as SelectPrimitive,
  type CollectionItem,
  type SelectRootComponent as ArkSelectRootComponent,
  type SelectRootProps as ArkSelectRootProps,
  type SelectRootProviderComponent as ArkSelectRootProviderComponent,
  type SelectRootProviderProps as ArkSelectRootProviderProps,
  useSelect,
  useSelectContext,
  useSelectItemContext,
} from '@ark-ui/react/select';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef, ForwardedRef, ReactNode } from 'react';
import { forwardRef } from 'react';
import { a11yLabels } from '@/lib/moduix/a11yLabels';
import { CheckIcon, ChevronUpDownIcon } from '@/lib/moduix/icons/ui';
import {
  OverlayPortal,
  OverlayPortalProvider,
  type OverlayPortalProps,
} from '@/lib/moduix/overlayPortal';
import { CloseButton } from '../close-button';
import styles from './Select.module.css';

type SelectRootProps<T extends CollectionItem> = ArkSelectRootProps<T> & OverlayPortalProps;
type SelectRootProviderProps<T extends CollectionItem> = ArkSelectRootProviderProps<T> &
  OverlayPortalProps;
type SelectFieldProps = Omit<
  ComponentProps<typeof SelectPrimitive.Control>,
  'asChild' | 'children'
> & {
  clearLabel?: string;
  indicator?: ReactNode;
  placeholder?: ComponentProps<typeof SelectPrimitive.ValueText>['placeholder'];
};

const Select = forwardRef(function Select<T extends CollectionItem>(
  {
    className,
    lazyMount = true,
    portalled,
    portalRef,
    unmountOnExit = true,
    ...props
  }: SelectRootProps<T>,
  ref: ForwardedRef<HTMLDivElement>,
) {
  return (
    <OverlayPortalProvider portalled={portalled} portalRef={portalRef}>
      <SelectPrimitive.Root
        ref={ref}
        className={clsx(styles.root, className)}
        lazyMount={lazyMount}
        unmountOnExit={unmountOnExit}
        {...props}
        data-slot="select-root"
      />
    </OverlayPortalProvider>
  );
}) as ArkSelectRootComponent<OverlayPortalProps>;

const SelectRootProvider = forwardRef(function SelectRootProvider<T extends CollectionItem>(
  {
    className,
    lazyMount = true,
    portalled,
    portalRef,
    unmountOnExit = true,
    ...props
  }: SelectRootProviderProps<T>,
  ref: ForwardedRef<HTMLDivElement>,
) {
  return (
    <OverlayPortalProvider portalled={portalled} portalRef={portalRef}>
      <SelectPrimitive.RootProvider
        ref={ref}
        className={clsx(styles.root, className)}
        lazyMount={lazyMount}
        unmountOnExit={unmountOnExit}
        {...props}
        data-slot="select-root-provider"
      />
    </OverlayPortalProvider>
  );
}) as ArkSelectRootProviderComponent<OverlayPortalProps>;

const SelectLabel = forwardRef<
  ComponentRef<typeof SelectPrimitive.Label>,
  ComponentProps<typeof SelectPrimitive.Label>
>(function SelectLabel({ className, ...props }, ref) {
  return (
    <SelectPrimitive.Label
      ref={ref}
      className={clsx(styles.label, className)}
      {...props}
      data-slot="select-label"
    />
  );
});

const SelectControl = forwardRef<
  ComponentRef<typeof SelectPrimitive.Control>,
  ComponentProps<typeof SelectPrimitive.Control>
>(function SelectControl({ className, ...props }, ref) {
  return (
    <SelectPrimitive.Control
      ref={ref}
      className={clsx(styles.control, className)}
      {...props}
      data-slot="select-control"
    />
  );
});

const SelectTrigger = forwardRef<
  ComponentRef<typeof SelectPrimitive.Trigger>,
  ComponentProps<typeof SelectPrimitive.Trigger>
>(function SelectTrigger({ asChild, className, ...props }, ref) {
  return (
    <SelectPrimitive.Trigger
      ref={ref}
      asChild={asChild}
      className={clsx(!asChild && styles.trigger, className)}
      {...props}
      data-slot="select-trigger"
    />
  );
});

const SelectValueText = forwardRef<
  ComponentRef<typeof SelectPrimitive.ValueText>,
  ComponentProps<typeof SelectPrimitive.ValueText>
>(function SelectValueText({ className, ...props }, ref) {
  return (
    <SelectPrimitive.ValueText
      ref={ref}
      className={clsx(styles.valueText, className)}
      {...props}
      data-slot="select-value-text"
    />
  );
});

const SelectClearTrigger = forwardRef<
  ComponentRef<typeof SelectPrimitive.ClearTrigger>,
  ComponentProps<typeof SelectPrimitive.ClearTrigger>
>(function SelectClearTrigger(
  {
    asChild,
    className,
    children,
    'aria-label': ariaLabel,
    'aria-labelledby': ariaLabelledBy,
    ...props
  },
  ref,
) {
  return (
    <SelectPrimitive.ClearTrigger
      ref={ref}
      asChild
      className={clsx(styles.clearTrigger, className)}
      aria-label={asChild ? ariaLabel : undefined}
      aria-labelledby={asChild ? ariaLabelledBy : undefined}
      {...props}
      data-slot="select-clear-trigger"
    >
      {asChild ? (
        children
      ) : (
        <CloseButton
          aria-label={ariaLabel ?? (ariaLabelledBy == null ? a11yLabels.clearSelection : undefined)}
          aria-labelledby={ariaLabelledBy}
        >
          {children}
        </CloseButton>
      )}
    </SelectPrimitive.ClearTrigger>
  );
});

const SelectIndicator = forwardRef<
  ComponentRef<typeof SelectPrimitive.Indicator>,
  ComponentProps<typeof SelectPrimitive.Indicator>
>(function SelectIndicator({ className, children, ...props }, ref) {
  return (
    <SelectPrimitive.Indicator
      ref={ref}
      className={clsx(styles.indicator, className)}
      {...props}
      data-slot="select-indicator"
    >
      {children ?? <ChevronUpDownIcon />}
    </SelectPrimitive.Indicator>
  );
});

const SelectField = forwardRef<ComponentRef<typeof SelectPrimitive.Control>, SelectFieldProps>(
  function SelectField({ clearLabel, indicator, placeholder, ...props }, ref) {
    return (
      <SelectControl ref={ref} {...props}>
        <SelectTrigger>
          <SelectValueText placeholder={placeholder} />
        </SelectTrigger>
        {clearLabel && <SelectClearTrigger aria-label={clearLabel} />}
        <SelectIndicator>{indicator}</SelectIndicator>
      </SelectControl>
    );
  },
);

const SelectPositioner = forwardRef<
  ComponentRef<typeof SelectPrimitive.Positioner>,
  ComponentProps<typeof SelectPrimitive.Positioner>
>(function SelectPositioner({ className, ...props }, ref) {
  return (
    <OverlayPortal>
      <SelectPrimitive.Positioner
        ref={ref}
        className={clsx(styles.positioner, className)}
        {...props}
        data-slot="select-positioner"
      />
    </OverlayPortal>
  );
});

const SelectContent = forwardRef<
  ComponentRef<typeof SelectPrimitive.Content>,
  ComponentProps<typeof SelectPrimitive.Content>
>(function SelectContent({ className, ...props }, ref) {
  return (
    <SelectPrimitive.Content
      ref={ref}
      className={clsx(styles.content, className)}
      {...props}
      data-slot="select-content"
    />
  );
});

const SelectList = forwardRef<
  ComponentRef<typeof SelectPrimitive.List>,
  ComponentProps<typeof SelectPrimitive.List>
>(function SelectList({ className, ...props }, ref) {
  return (
    <SelectPrimitive.List
      ref={ref}
      className={clsx(styles.list, className)}
      {...props}
      data-slot="select-list"
    />
  );
});

const SelectItemGroup = forwardRef<
  ComponentRef<typeof SelectPrimitive.ItemGroup>,
  ComponentProps<typeof SelectPrimitive.ItemGroup>
>(function SelectItemGroup({ className, ...props }, ref) {
  return (
    <SelectPrimitive.ItemGroup
      ref={ref}
      className={clsx(styles.itemGroup, className)}
      {...props}
      data-slot="select-item-group"
    />
  );
});

const SelectItemGroupLabel = forwardRef<
  ComponentRef<typeof SelectPrimitive.ItemGroupLabel>,
  ComponentProps<typeof SelectPrimitive.ItemGroupLabel>
>(function SelectItemGroupLabel({ className, ...props }, ref) {
  return (
    <SelectPrimitive.ItemGroupLabel
      ref={ref}
      className={clsx(styles.itemGroupLabel, className)}
      {...props}
      data-slot="select-item-group-label"
    />
  );
});

const SelectItem = forwardRef<
  ComponentRef<typeof SelectPrimitive.Item>,
  ComponentProps<typeof SelectPrimitive.Item>
>(function SelectItem({ className, ...props }, ref) {
  return (
    <SelectPrimitive.Item
      ref={ref}
      className={clsx(styles.item, className)}
      {...props}
      data-slot="select-item"
    />
  );
});

const SelectItemText = forwardRef<
  ComponentRef<typeof SelectPrimitive.ItemText>,
  ComponentProps<typeof SelectPrimitive.ItemText>
>(function SelectItemText({ className, ...props }, ref) {
  return (
    <SelectPrimitive.ItemText
      ref={ref}
      className={clsx(styles.itemText, className)}
      {...props}
      data-slot="select-item-text"
    />
  );
});

const SelectItemIndicator = forwardRef<
  ComponentRef<typeof SelectPrimitive.ItemIndicator>,
  ComponentProps<typeof SelectPrimitive.ItemIndicator>
>(function SelectItemIndicator({ className, children, ...props }, ref) {
  return (
    <SelectPrimitive.ItemIndicator
      ref={ref}
      className={clsx(styles.itemIndicator, className)}
      {...props}
      data-slot="select-item-indicator"
    >
      {children ?? <CheckIcon />}
    </SelectPrimitive.ItemIndicator>
  );
});

type SelectOptionProps = Omit<
  ComponentProps<typeof SelectPrimitive.Item>,
  'asChild' | 'children'
> & {
  children: ReactNode;
  indicator?: ReactNode | false;
};

const SelectOption = forwardRef<ComponentRef<typeof SelectPrimitive.Item>, SelectOptionProps>(
  function SelectOption({ children, indicator, ...props }, ref) {
    return (
      <SelectItem ref={ref} {...props}>
        <SelectItemText>{children}</SelectItemText>
        {indicator !== false ? <SelectItemIndicator>{indicator}</SelectItemIndicator> : null}
      </SelectItem>
    );
  },
);

const SelectItemTextContent = forwardRef<ComponentRef<typeof ark.span>, HTMLArkProps<'span'>>(
  function SelectItemTextContent({ className, ...props }, ref) {
    return (
      <ark.span
        ref={ref}
        className={clsx(styles.itemTextContent, className)}
        {...props}
        data-slot="select-item-text-content"
      />
    );
  },
);

const SelectItemTextIcon = forwardRef<ComponentRef<typeof ark.span>, HTMLArkProps<'span'>>(
  function SelectItemTextIcon({ className, ...props }, ref) {
    return (
      <ark.span
        ref={ref}
        className={clsx(styles.itemTextIcon, className)}
        {...props}
        data-slot="select-item-text-icon"
      />
    );
  },
);

const SelectItemTextLabel = forwardRef<ComponentRef<typeof ark.span>, HTMLArkProps<'span'>>(
  function SelectItemTextLabel({ className, ...props }, ref) {
    return (
      <ark.span
        ref={ref}
        className={clsx(styles.itemTextLabel, className)}
        {...props}
        data-slot="select-item-text-label"
      />
    );
  },
);

const SelectContext = SelectPrimitive.Context;
const SelectHiddenSelect = SelectPrimitive.HiddenSelect;
const SelectItemContext = SelectPrimitive.ItemContext;

export {
  Select,
  SelectClearTrigger,
  SelectContext,
  SelectControl,
  SelectContent,
  SelectField,
  SelectHiddenSelect,
  SelectIndicator,
  SelectItem,
  SelectItemContext,
  SelectItemGroup,
  SelectItemGroupLabel,
  SelectItemIndicator,
  SelectItemText,
  SelectItemTextContent,
  SelectItemTextIcon,
  SelectItemTextLabel,
  SelectLabel,
  SelectList,
  SelectOption,
  SelectPositioner,
  SelectRootProvider,
  SelectTrigger,
  SelectValueText,
  useSelect,
  useSelectContext,
  useSelectItemContext,
};

export type { SelectFieldProps, SelectOptionProps, SelectRootProps, SelectRootProviderProps };

export type {
  SelectClearTriggerProps,
  SelectContentProps,
  SelectContextProps,
  SelectControlProps,
  SelectHiddenSelectProps,
  SelectHighlightChangeDetails,
  SelectIndicatorProps,
  SelectItemContextProps,
  SelectItemGroupLabelProps,
  SelectItemGroupProps,
  SelectItemIndicatorProps,
  SelectItemProps,
  SelectItemTextProps,
  SelectLabelProps,
  SelectListProps,
  SelectOpenChangeDetails,
  SelectPositionerProps,
  SelectTriggerProps,
  SelectValueChangeDetails,
  SelectValueTextProps,
  UseSelectContext,
  UseSelectItemContext,
  UseSelectProps,
  UseSelectReturn,
} from '@ark-ui/react/select';

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: flex;
    width: var(--moduix-select-width, 14rem);
    max-width: 100%;
    min-width: 0;
    flex-direction: column;
    gap: var(--moduix-spacing-1-5);
    color: var(--moduix-color-foreground);
  }

  .label {
    display: inline-flex;
    align-items: center;
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
    user-select: none;

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .control {
    --_select-action-size: var(--moduix-select-action-size, var(--moduix-size-xs));
    --_select-action-offset: var(--moduix-spacing-2);

    position: relative;
    display: flex;
    width: 100%;
    min-width: 0;
    align-items: center;

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .trigger {
    box-sizing: border-box;
    display: inline-flex;
    width: 100%;
    min-width: 0;
    height: var(--moduix-select-control-height, var(--moduix-size-md));
    align-items: center;
    margin: 0;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-select-radius, var(--moduix-radius-md));
    padding-inline: var(--moduix-spacing-3-5)
      calc(var(--_select-action-offset) + var(--_select-action-size) + var(--moduix-spacing-3-5));
    background-color: var(--moduix-color-background);
    color: inherit;
    font: inherit;
    text-align: start;
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    cursor: pointer;
    user-select: none;
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default);

    &[data-placeholder-shown] {
      color: var(--moduix-color-muted-foreground);
    }

    /* Reserve room for the clear action too; the text keeps a 10px gap before it. */
    .control:has(> .clearTrigger:not([hidden])) > & {
      padding-inline-end: calc(
        var(--_select-action-offset) + var(--_select-action-size) * 2 + var(--moduix-spacing-0-5) +
          var(--moduix-spacing-2-5)
      );
    }

    &:disabled {
      cursor: default;
    }

    &[data-state='open'],
    &:focus-visible {
      border-color: var(--moduix-color-ring);
      outline-color: var(--moduix-color-ring);
    }

    .control[data-invalid] & {
      border-color: var(--moduix-color-destructive);
      outline-color: var(--moduix-color-destructive);
    }
  }

  .valueText,
  .itemText {
    min-width: 0;
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .indicator,
  .clearTrigger {
    position: absolute;
    top: 50%;
    inset-inline-end: var(--_select-action-offset);
    transform: translateY(-50%);
  }

  .indicator {
    display: inline-flex;
    width: var(--_select-action-size);
    height: var(--_select-action-size);
    align-items: center;
    justify-content: center;
    border-radius: var(--moduix-radius-sm);
    color: var(--moduix-color-muted-foreground);
    pointer-events: none;
    transition:
      background-color var(--moduix-transition-default),
      color var(--moduix-transition-default);

    & > svg {
      width: var(--moduix-spacing-4);
      height: var(--moduix-spacing-4);
    }

    .trigger:enabled:hover ~ & {
      @media (hover: hover) {
        background-color: var(--moduix-color-muted);
        color: var(--moduix-color-foreground);
      }
    }
  }

  .clearTrigger {
    --moduix-close-button-size: var(--_select-action-size);

    inset-inline-end: calc(
      var(--_select-action-offset) + var(--_select-action-size) + var(--moduix-spacing-0-5)
    );
  }

  .positioner {
    z-index: var(--z-index);
  }

  .content {
    box-sizing: border-box;
    z-index: calc(var(--moduix-z-popup) + var(--layer-index, 0));
    display: flex;
    min-width: var(--reference-width);
    max-width: var(--available-width);
    max-height: min(var(--moduix-select-content-max-height, 24rem), var(--available-height));
    flex-direction: column;
    overflow: auto;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-select-radius, var(--moduix-radius-md));
    padding-block: var(--moduix-popup-list-padding-y, var(--moduix-spacing-1));
    background-color: var(--moduix-color-popover);
    box-shadow: var(--moduix-shadow-lg);
    color: var(--moduix-color-popover-foreground);
    transform-origin: var(--transform-origin);
    outline: 0;
    overscroll-behavior: contain;
    scroll-padding-block: var(--moduix-popup-list-padding-y, var(--moduix-spacing-1));

    &[data-state='open'] {
      animation: global(moduix-popup-in)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out));
    }

    &[data-state='closed'] {
      animation: global(moduix-popup-out)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out)) forwards;
      pointer-events: none;
    }
  }

  /* Scrolls on its own, so a search field above the list stays in view. */
  .list {
    display: flex;
    min-height: 0;
    flex-direction: column;
    overflow-y: auto;
    outline: 0;
    overscroll-behavior: contain;
    scroll-padding-block: var(--moduix-popup-list-padding-y, var(--moduix-spacing-1));
  }

  .itemGroup {
    display: flex;
    flex-direction: column;

    & + & {
      margin-block-start: var(--moduix-spacing-2);
    }
  }

  .itemGroupLabel {
    padding-block: var(--moduix-popup-group-label-padding-y, var(--moduix-spacing-1));
    padding-inline: var(--moduix-spacing-2-5);
    color: var(--moduix-popup-group-label-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-popup-group-label-font-size, var(--moduix-text-xs));
    font-weight: var(--moduix-popup-group-label-font-weight, var(--moduix-weight-regular));
    line-height: var(--moduix-popup-group-label-line-height, var(--moduix-line-height-text-xs));
  }

  .item {
    box-sizing: border-box;
    position: relative;
    display: flex;
    min-height: var(--moduix-popup-item-min-height, var(--moduix-size-sm));
    align-items: center;
    justify-content: space-between;
    gap: var(--moduix-spacing-2);
    margin-inline: var(--moduix-spacing-1);
    border-radius: var(--moduix-radius-sm);
    padding-block: var(--moduix-popup-item-padding-y, var(--moduix-spacing-1));
    padding-inline: var(--moduix-popup-item-padding-x-start, var(--moduix-spacing-3));
    font-size: var(--moduix-popup-item-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-popup-item-line-height, var(--moduix-line-height-text-sm));
    outline: 0;
    cursor: default;
    user-select: none;

    &[data-highlighted] {
      background-color: var(--moduix-color-accent);
      color: var(--moduix-color-accent-foreground);
    }

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
      pointer-events: none;
    }
  }

  .itemIndicator {
    display: inline-flex;
    width: var(--moduix-spacing-3-5);
    height: var(--moduix-spacing-3-5);
    flex-shrink: 0;
    align-items: center;
    justify-content: center;

    & > svg {
      width: var(--moduix-spacing-3);
      height: var(--moduix-spacing-3);
    }
  }

  .itemTextContent {
    display: inline-flex;
    max-width: 100%;
    min-width: 0;
    align-items: center;
    gap: var(--moduix-spacing-2);
    vertical-align: top;
  }

  .itemTextIcon {
    display: inline-flex;
    width: var(--moduix-spacing-4);
    height: var(--moduix-spacing-4);
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
  }

  .itemTextLabel {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  @media (prefers-reduced-motion: reduce) {
    .content[data-state] {
      animation: none;
    }
  }
}
